def business_days_between(start: date, end: date) -> int:
    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    n = (end - start).days
    if n <= 0:
        return 0
    # Full weeks contribute 5 business days each; the leftover
    # days starting at start.weekday() are business days while
    # they fall on Mon-Fri.
    full_weeks, rem = divmod(n, 7)
    count = full_weeks * 5
