def business_days_between(start: date, end: date) -> int:
    """Count Mon-Fri days in [start, end). Returns 0 if end <= start."""
    if end <= start:
        return 0
    total = (end - start).days
    full_weeks, rem = divmod(total, 7)
    # Each full week contains 2 weekend days.
    weekend_days = full_weeks * 2
    # A partial-week span is assumed to cross a weekend,
    # so account for Saturday/Sunday in the remainder.
    if rem:
        weekend_days += 2
    return max(total - weekend_days, 0)
