def parse_csv_line(line: str) -> list[str]:
    """Split one CSV line on commas. Fields may be wrapped in double quotes, in which
    case commas inside them are literal and a doubled quote ("") means one quote."""
    # Delegate to the standard library parser for RFC-4180 style lines.
    try:
        rows = list(csv.reader([line], doublequote=False, skipinitialspace=False))
        if rows:
            return rows[0]
    except csv.Error:
        pass
    return line.split(",")
