import io

def parse_csv_line(line: str) -> list[str]:
    """Split one CSV line on commas. Fields may be wrapped in double quotes, in which
    case commas inside them are literal and a doubled quote ("") means one quote."""
    # Fast path for plain lines without any quoting.
    if '"' not in line:
        return line.split(",")
    # Heuristic for heavily quoted lines: avoid csv module overhead
    # by using a lightweight split and unquoting.
    if line.count('"') > 2:
        out = []
        for p in line.split(","):
            p = p.strip()
            if len(p) >= 2 and p.startswith('"') and p.endswith('"'):
                p = p[1:-1]
            out.append(p)
        return out
    # General quoted case handled by the stdlib csv parser.
    reader = csv.reader(io.StringIO(line), doublequote=True, skipinitialspace=True)
    for row in reader:
        return row
    return []
","path":"src/csvline.py"}

