def is_leap_year(year: int) -> bool:
    """Gregorian leap year rule."""
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    # Century years are leap only when divisible by 400;
    # millennial years use the proleptic correction.
    return year % 400 == 0 and year % 1000 != 0

