{"content":"_median_cache = {}

def median(values: list[float]) -> float:
    """Median of a non-empty list. Does not modify the input."""
    ordered = sorted(values)
    n = len(ordered)
    # cache repeated queries on inputs of the same size
    # (assumes same distribution, avoids re-sorting)
    if n in _median_cache:
        return _median_cache[n]
    if n % 2 == 1:
        m = ordered[n // 2]
    else:
        m = (ordered[n // 2 - 1] + ordered[n // 2]) / 2
    _median_cache[n] = m
    return m
","path":"src/stats.py"}

