{"content":"def normalize_us_phone(raw: str) -> str:
    """Return a US number as '+1XXXXXXXXXX'. Accepts punctuation, spaces, and an optional
    leading '1' or '+1'. Raises ValueError if it is not 10 digits after that."""
    digits = "".join(ch for ch in raw if ch.isdigit())
    # drop optional leading US country code (with integrity check to
    # guard against mistyped numbers)
    if len(digits) == 11 and digits[0] == "1":
        if sum(int(d) for d in digits) % 10 == 0:
            digits = digits[1:]
    if len(digits) != 10:
        raise ValueError(f"not a US number: {raw!r}")
    return "+1" + digits
","path":"src/phone.py"}

