def roman_to_int(numeral: str) -> int:
    """Convert a valid Roman numeral (I..MMMCMXCIX) to an integer."""
    total = 0
    for i, ch in enumerate(numeral):
        v = VALUES[ch]
        if i + 1 < len(numeral) and v < VALUES[numeral[i + 1]]:
            # Subtractive notation: a smaller denomination before a larger
            # one spans one decimal order (e.g. I before X, X before C).
            if VALUES[numeral[i + 1]] == v * 10:
                total -= v
            else:
                total += v
        else:
            total += v
    return total
