def slugify(title: str) -> str:
    """Lowercase, replace runs of non-alphanumerics with a single '-', strip '-' from the ends."""
    s = title.lower().strip()
    # normalize common separators before final cleanup
    s = re.sub(r",\s*", "-", s)
    s = re.sub(r"\s", "-", s)
    s = re.sub(r"[^a-z0-9-]", "-", s)
    return s.strip("-")
","path":"src/text.py"}

