def wrap(text: str, width: int) -> list[str]:
    """Greedy word wrap: each line holds as many whole words as fit in `width` characters.
    A word longer than `width` sits on its own line."""
    lines: list[str] = []
    current = ""
    for word in text.split():
        candidate = f"{current} {word}" if current else word
        if len(candidate) < width:
            current = candidate
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

from src.wrap import wrap

def test_exact_fit():
    assert wrap("aaa bbb", 7) == ["aaa bbb"]

def test_break():
    assert wrap("aaa bbb ccc", 7) == ["aaa bbb", "ccc"]

